                        const element = node;
                        const candidates = [];
                        if (element.matches && element.matches('[data-message-author-role="user"]')) {
                            candidates.push(element);
                        }
                        if (element.querySelectorAll) {
                            candidates.push(...element.querySelectorAll('[data-message-author-role="user"]'));
                        }
