                            limitWarningDelay: TTSReader.CONFIG.LIMIT_WARNING_DELAY_MS,
                            navCtrlJumpSegments: TTSReader.CONFIG.NAV_CTRL_JUMP_SEGMENTS,
                            speedStep: TTSReader.CONFIG.SPEED_STEP
                        }
                    });
                    return true;
            }

            return false;
        });
