        if (sendButton && !sendButton.disabled) {
            sendButton.click();
            return true;
        }
        return false;
    };

    setTimeout(() => {
        if (clickSend()) return;
        const observer = new MutationObserver((mutations, obs) => {
            if (clickSend()) {
                obs.disconnect();
            }
        });

        observer.observe(document.body, {
            childList: true,
            subtree: true,
            attributes: true,
            attributeFilter: ['disabled']
        });
        setTimeout(() => observer.disconnect(), 5000);
    }, 40);
}

